<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";
import type { Pige360SessionClient } from "@pige360/auth";
type Row=Record<string,any>;
const props=defineProps<{api:Pige360SessionClient}>();const emit=defineEmits<{error:[message:string]}>();const loading=ref(false),notice=ref("");const locations=ref<Row[]>([]),menus=ref<Row[]>([]),wallets=ref<Row[]>([]),subsidies=ref<Row[]>([]),students=ref<Row[]>([]),products=ref<Row[]>([]);
const locationForm=reactive({unit_id:"",code:"CANT-01",name:"Cantina Principal"});const menuForm=reactive({canteen_location_id:"",name:"Cardápio Regular",starts_on:"",ends_on:""});const walletForm=reactive({student_id:"",daily_limit:"50.00",weekly_limit:"250.00"});const creditForm=reactive({wallet_id:"",amount:"",method:"pix",external_reference:"",reason:"Recarga da carteira"});const subsidyForm=reactive({student_id:"",subsidy_type:"fixed",amount:"",percentage:"",valid_from:new Date().toISOString().slice(0,10),valid_until:"",reason:"Benefício institucional"});
function msg(e:unknown){return e instanceof Error?e.message:"Erro inesperado";}async function request<T=Row>(p:string,i:RequestInit={}){return props.api.request<T>(p,i)}async function post<T=Row>(p:string,b:any,key?:string){const h:Record<string,string>={"Content-Type":"application/json"};if(key)h["Idempotency-Key"]=key;return request<T>(p,{method:"POST",headers:h,body:JSON.stringify(b)})}
async function load(){loading.value=true;try{const [l,m,w,s,refs,p]=await Promise.all([request<Row>("/canteen/locations"),request<Row>("/canteen/menus"),request<Row>("/canteen/wallets"),request<Row>("/canteen/subsidies"),request<Row>("/references/catalog"),request<Row>("/products")]);locations.value=l.items||[];menus.value=m.items||[];wallets.value=w.items||[];subsidies.value=s.items||[];students.value=refs.students||[];products.value=p.items||[];if(!menuForm.canteen_location_id&&locations.value[0])menuForm.canteen_location_id=locations.value[0].id;}catch(e){emit("error",msg(e))}finally{loading.value=false}}
async function createLocation(){try{await post("/canteen/locations",{...locationForm,unit_id:locationForm.unit_id||null});notice.value="Cantina cadastrada.";await load()}catch(e){emit("error",msg(e))}}
async function createMenu(){try{const menu=await post<Row>("/canteen/menus",{...menuForm,starts_on:menuForm.starts_on||null,ends_on:menuForm.ends_on||null});for(const product of products.value.filter(x=>x.product_type==='food').slice(0,20))await post(`/canteen/menus/${menu.id}/items`,{product_id:product.id});notice.value="Cardápio criado; adicione/ajuste itens e publique quando estiver pronto.";await load()}catch(e){emit("error",msg(e))}}
async function publishMenu(row:Row){try{await post(`/canteen/menus/${row.id}/state`,{state:"active",reason:"Cardápio aprovado pelo gestor"});await load()}catch(e){emit("error",msg(e))}}
async function createWallet(){try{const w=await post<Row>("/canteen/wallets",walletForm);creditForm.wallet_id=w.id;notice.value="Carteira criada.";await load()}catch(e){emit("error",msg(e))}}
async function credit(){try{await post(`/canteen/wallets/${creditForm.wallet_id}/credits`,{amount:creditForm.amount,method:creditForm.method,external_reference:creditForm.external_reference||null,reason:creditForm.reason},`wallet-${crypto.randomUUID()}`);notice.value="Recarga confirmada.";await load()}catch(e){emit("error",msg(e))}}
async function subsidy(){try{await post("/canteen/subsidies",{student_id:subsidyForm.student_id,subsidy_type:subsidyForm.subsidy_type,amount:subsidyForm.subsidy_type==='fixed'?subsidyForm.amount:null,percentage:subsidyForm.subsidy_type==='percentage'?subsidyForm.percentage:null,valid_from:subsidyForm.valid_from,valid_until:subsidyForm.valid_until||null,reason:subsidyForm.reason});notice.value="Subsídio registrado.";await load()}catch(e){emit("error",msg(e))}}
onMounted(load);
</script>
<template><div v-if="notice" class="flash success">{{notice}}</div><section class="grid-2 forms"><form class="panel" @submit.prevent="createLocation"><h2>Unidade de cantina</h2><label>Código<input v-model="locationForm.code" required></label><label>Nome<input v-model="locationForm.name" required></label><button class="primary">Cadastrar</button></form><form class="panel" @submit.prevent="createMenu"><h2>Novo cardápio</h2><label>Cantina<select v-model="menuForm.canteen_location_id" required><option v-for="x in locations" :value="x.id">{{x.name}}</option></select></label><label>Nome<input v-model="menuForm.name" required></label><div class="cols"><label>Início<input v-model="menuForm.starts_on" type="date"></label><label>Fim<input v-model="menuForm.ends_on" type="date"></label></div><button class="primary">Criar cardápio</button></form></section><section class="grid-2 forms"><form class="panel" @submit.prevent="createWallet"><h2>Carteira do aluno</h2><label>Aluno<select v-model="walletForm.student_id" required><option v-for="x in students" :value="x.id">{{x.label}}</option></select></label><div class="cols"><label>Limite diário<input v-model="walletForm.daily_limit" type="number" step="0.01"></label><label>Limite semanal<input v-model="walletForm.weekly_limit" type="number" step="0.01"></label></div><button class="primary">Criar carteira</button></form><form class="panel" @submit.prevent="credit"><h2>Recarga</h2><label>Carteira<select v-model="creditForm.wallet_id" required><option v-for="x in wallets" :value="x.id">{{x.student_name}} · saldo {{Number(x.balance).toFixed(2)}}</option></select></label><label>Valor<input v-model="creditForm.amount" type="number" step="0.01" min="0.01" required></label><label>Referência<input v-model="creditForm.external_reference"></label><button class="primary">Confirmar recarga</button></form></section><section class="grid-2 forms"><form class="panel" @submit.prevent="subsidy"><h2>Subsídio</h2><label>Aluno<select v-model="subsidyForm.student_id" required><option v-for="x in students" :value="x.id">{{x.label}}</option></select></label><label>Tipo<select v-model="subsidyForm.subsidy_type"><option value="fixed">Valor fixo</option><option value="percentage">Percentual</option><option value="free_meal">Refeição gratuita</option></select></label><label v-if="subsidyForm.subsidy_type==='fixed'">Valor<input v-model="subsidyForm.amount" type="number" step="0.01"></label><label v-if="subsidyForm.subsidy_type==='percentage'">Percentual<input v-model="subsidyForm.percentage" type="number" step="0.01"></label><div class="cols"><label>Início<input v-model="subsidyForm.valid_from" type="date" required></label><label>Fim<input v-model="subsidyForm.valid_until" type="date"></label></div><button class="primary">Registrar subsídio</button></form><div class="panel"><h2>Políticas aplicadas no PDV</h2><ul class="checklist"><li>Alergênicos e produtos bloqueados são validados antes da baixa de estoque.</li><li>Limites diário/semanal consideram consumo líquido.</li><li>Carteira e estoque são atualizados na mesma transação.</li><li>Subsídio institucional não vira crédito na devolução.</li></ul></div></section><section class="panel"><div class="panel-title"><h2>Cardápios</h2><span>{{menus.length}}</span></div><table><thead><tr><th>Cardápio</th><th>Vigência</th><th>Itens</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="m in menus" :key="m.id"><td>{{m.name}}</td><td>{{m.starts_on||'—'}} → {{m.ends_on||'—'}}</td><td>{{m.items?.length||0}}</td><td>{{m.state}}</td><td><button v-if="m.state==='draft'" class="small" @click="publishMenu(m)">Publicar</button></td></tr></tbody></table></section><section class="panel"><div class="panel-title"><h2>Carteiras</h2><span>{{wallets.length}}</span></div><table><thead><tr><th>Aluno</th><th>Saldo</th><th>Diário</th><th>Semanal</th><th>Estado</th></tr></thead><tbody><tr v-for="w in wallets" :key="w.id"><td>{{w.student_name}}</td><td>R$ {{Number(w.balance).toFixed(2)}}</td><td>{{w.daily_limit??'—'}}</td><td>{{w.weekly_limit??'—'}}</td><td>{{w.state}}</td></tr></tbody></table></section></template>
